UPDATE user_coupon
SET status = 'LOCKED', lock_time = #{now}
WHERE id = #{id} AND user_id = #{userId} AND status = 'UNUSED'

UPDATE user_coupon
SET status = 'USED', used_time = #{now}
WHERE order_id = #{orderId} AND status = 'LOCKED'

UPDATE user_coupon
SET status = 'UNUSED', order_id = NULL, used_time = NULL, lock_time = NULL
WHERE order_id = #{orderId} AND status = 'USED' AND end_time > #{now}

UPDATE coupon_template
SET is_deleted = 1, update_time = #{now}
WHERE id = #{id} AND is_deleted = 0

UPDATE coupon_template
SET manual_status = 1, update_time = #{now}
WHERE id = #{id} AND is_deleted = 0
